  X,
  Printer,
  ChevronRight,
  ClipboardList,
  MessageCircle,
  History,
  User,
  BellRing,
  Lock,
  Unlock,
  Shirt,
  Waves,
  Sparkles,
  Droplets
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
