              onClick={() => setShowWelcome(true)}
              className="mt-8 text-xs font-bold text-blue-600 hover:underline"
            >
              Kembali ke Beranda
            </button>
          </Card>
        </div>

        <a 
          href={`https://wa.me/6285695014434?text=${encodeURIComponent(whatsappOrderTemplate)}`}
