            </div>
            <span className="font-black text-lg text-blue-800 tracking-tight">IBU TINI</span>
          </div>
          <h2 className="hidden md:block text-2xl font-black text-gray-800 tracking-tight">
            {role === 'ADMIN' ? 'Control Panel Admin' : 'Pesanan Anda'}
