      message: `Status order ${order.notaNumber} (${order.customerName}) diubah ke ${newStatus}`, 
      type: 'success' 
    });
    setTimeout(() => setToast(null), 4000);
  };

  const stats = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const monthlyOrders = orders.filter(o => {
      const d = new Date(o.createdAt);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const omzet = monthlyOrders.reduce((acc, curr) => acc + curr.totalPrice, 0);
    const completed = monthlyOrders.filter(o => o.status === 'Selesai').length;
    const process = monthlyOrders.filter(o => o.status === 'Proses').length;

    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - (6 - i));
      const dateStr = d.toLocaleDateString('id-ID', { weekday: 'short' });
      const dayTotal = orders
        .filter(o => new Date(o.createdAt).toDateString() === d.toDateString())
        .reduce((sum, o) => sum + o.totalPrice, 0);
      return { name: dateStr, revenue: dayTotal };
    });

    return { omzet, completed, process, chartData: last7Days };
  }, [orders]);

  const filteredOrders = useMemo(() => {
    let result = orders;

    // Filter by role/phone
    if (role === 'CUSTOMER' && customerPhone) {
      result = result.filter(o => o.customerPhone === customerPhone);
    }

    // Filter by status
    if (statusFilter !== 'Semua') {
      result = result.filter(o => o.status === statusFilter);
    }

    // Filter by service type
    if (serviceFilter !== 'Semua') {
      result = result.filter(o => o.serviceType === serviceFilter);
    }

    // Filter by date range
    if (startDate) {
      const start = new Date(startDate);
      start.setHours(0, 0, 0, 0);
      result = result.filter(o => new Date(o.createdAt) >= start);
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      result = result.filter(o => new Date(o.createdAt) <= end);
    }

    // Filter by search query
    if (searchQuery) {
      result = result.filter(o => 
        o.customerName.toLowerCase().includes(searchQuery.toLowerCase()) || 
        o.notaNumber.toLowerCase().includes(searchQuery.toLowerCase()) ||
        o.customerPhone.includes(searchQuery)
      );
    }
    return result;
  }, [orders, role, customerPhone, searchQuery, statusFilter, serviceFilter, startDate, endDate]);

  // Counts for each filter button based on current role's orders and date filters
  const filterCounts = useMemo(() => {
    let baseOrders = role === 'CUSTOMER' 
      ? orders.filter(o => o.customerPhone === customerPhone) 
      : orders;

    // Applying date range to counts as well for consistency
    if (startDate) {
      const start = new Date(startDate);
      start.setHours(0, 0, 0, 0);
      baseOrders = baseOrders.filter(o => new Date(o.createdAt) >= start);
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      baseOrders = baseOrders.filter(o => new Date(o.createdAt) <= end);
    }

    return {
      'Semua': baseOrders.length,
      'Baru': baseOrders.filter(o => o.status === 'Baru').length,
      'Proses': baseOrders.filter(o => o.status === 'Proses').length,
      'Selesai': baseOrders.filter(o => o.status === 'Selesai').length,
    };
  }, [orders, role, customerPhone, startDate, endDate]);

  const exportToCSV = () => {
    // We export the current filtered results or all results
    const dataToExport = filteredOrders;
    if (dataToExport.length === 0) {
      setToast({ message: "Tidak ada data untuk diekspor", type: 'info' });
      return;
    }

    const headers = [
      "No Nota", "Tanggal Masuk", "Pelanggan", "No HP", "Alamat", 
      "Layanan", "Berat/Qty", "Total Harga", "Status", "Estimasi Selesai", 
      "Catatan", "Metode"
    ];

    const rows = dataToExport.map(o => [
      o.notaNumber,
      new Date(o.createdAt).toLocaleDateString('id-ID'),
      o.customerName,
      o.customerPhone,
      `"${o.customerAddress.replace(/"/g, '""')}"`, // Quote escape
      o.serviceType,
      o.weight,
      o.totalPrice,
      o.status,
      new Date(o.estimatedFinishDate).toLocaleDateString('id-ID'),
      `"${(o.specialRequest || "").replace(/"/g, '""')}"`,
      o.deliveryMethod
    ]);

    const csvContent = [
      headers.join(","),
      ...rows.map(r => r.join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `Data_Laundry_TINI_${new Date().toISOString().slice(0,10)}.csv`);
