function OrderForm({ role, prefilledPhone, onAdd }: any) {
  const [formData, setFormData] = useState({
    customerName: '',
    customerPhone: prefilledPhone || '',
    customerAddress: '',
    weight: 0,
    serviceType: 'Cuci Setrika' as ServiceType,
    specialRequest: '',
    deliveryMethod: 'Ambil Sendiri' as any
  });

  const total = formData.weight * SERVICE_PRICES[formData.serviceType];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newOrder: Order = {
      id: Date.now().toString(),
      notaNumber: generateNotaNumber(),
      ...formData,
      totalPrice: total,
      status: 'Baru',
      createdAt: new Date().toISOString(),
      estimatedFinishDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString(),
    };
    onAdd(newOrder, true);
    setFormData({ customerName: '', customerPhone: prefilledPhone || '', customerAddress: '', weight: 0, serviceType: 'Cuci Setrika', specialRequest: '', deliveryMethod: 'Ambil Sendiri' });
  };

  return (
    <div className="max-w-3xl mx-auto">
      <Card className="shadow-2xl">
        <h3 className="text-2xl font-black text-gray-800 tracking-tight mb-10">Input Pesanan Baru</h3>
        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <input required className="w-full px-5 py-4 bg-white/50 border border-blue-100 rounded-2xl outline-none" placeholder="Nama Lengkap" value={formData.customerName} onChange={(e) => setFormData({...formData, customerName: e.target.value})} />
            <input required className="w-full px-5 py-4 bg-white/50 border border-blue-100 rounded-2xl outline-none" placeholder="No WhatsApp" value={formData.customerPhone} onChange={(e) => setFormData({...formData, customerPhone: e.target.value})} />
          </div>
          <textarea required className="w-full px-5 py-4 bg-white/50 border border-blue-100 rounded-2xl outline-none resize-none" placeholder="Alamat Penjemputan" value={formData.customerAddress} onChange={(e) => setFormData({...formData, customerAddress: e.target.value})} />
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <input required type="number" min="0.1" step="0.1" className="w-full px-5 py-4 bg-white/50 border border-blue-100 rounded-2xl outline-none font-black text-xl" value={formData.weight} onChange={(e) => setFormData({...formData, weight: parseFloat(e.target.value) || 0})} />
            <select className="md:col-span-2 w-full px-5 py-4 bg-white/50 border border-blue-100 rounded-2xl outline-none font-bold" value={formData.serviceType} onChange={(e) => setFormData({...formData, serviceType: e.target.value as ServiceType})}>
              {Object.keys(SERVICE_PRICES).map(s => <option key={s} value={s}>{s} (Rp {SERVICE_PRICES[s as ServiceType].toLocaleString()})</option>)}
            </select>
          </div>
          <div className="p-6 bg-gradient-to-br from-blue-50 to-white rounded-3xl flex items-center justify-between border border-blue-100">
            <div>
              <p className="text-[10px] text-blue-600 font-black uppercase tracking-widest mb-1">Total</p>
              <p className="text-4xl font-black text-blue-700 tracking-tighter">{formatIDR(total)}</p>
            </div>
            <Button type="submit" disabled={total <= 0} className="px-12 py-5 text-xl">Daftarkan <ArrowRight className="w-6 h-6" /></Button>
          </div>
        </form>
      </Card>
    </div>
  );
}

