      <div className="space-y-4 mb-8">
        <div className="flex items-center gap-3 text-sm font-bold text-gray-600"><Package className="w-4 h-4" /> {order.serviceType} ({order.weight} unit)</div>
        <div className="flex items-center gap-3 text-sm font-bold text-gray-600"><Clock className="w-4 h-4" /> Ambil: {new Date(order.estimatedFinishDate).toLocaleDateString('id-ID')}</div>
      </div>
      <div className="pt-6 border-t border-white/60 flex items-center justify-between mb-6">
        <p className="text-2xl font-black text-blue-700 tracking-tighter">{formatIDR(order.totalPrice)}</p>
