            <Button type="submit" disabled={total <= 0} className="bg-white text-blue-600 hover:bg-gray-50 w-full md:w-auto px-10 py-4">DAFTARKAN SEKARANG</Button>
          </div>
        </form>
      </Card>
    </div>
  );
}

