export default function App() {
  const [role, setRole] = useState<Role | null>(null);
  const [customerPhone, setCustomerPhone] = useState<string>('');
  const [orders, setOrders] = useState<Order[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showSplash, setShowSplash] = useState(true);
  const [showWelcome, setShowWelcome] = useState(false);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'orders' | 'add'>('dashboard');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<'Semua' | OrderStatus>('Semua');
  const [serviceFilter, setServiceFilter] = useState<ServiceType | 'Semua'>('Semua');
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'info' } | null>(null);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);

  // Cloud State
  const [cloudBinId, setCloudBinId] = useState<string | null>(null);
  const [cloudStatus, setCloudStatus] = useState<'idle' | 'syncing' | 'error' | 'connected'>('idle');

  // Auth state for Admin
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPinInput, setAdminPinInput] = useState('');
  const [adminPinError, setAdminPinError] = useState(false);

  // --- Initialization Flow ---
  const connectToCloud = useCallback(async (existingOrders: Order[]) => {
    setCloudStatus('syncing');
    try {
        let binId = localStorage.getItem('tini_cloud_bin_id');

        if (binId) {
            const cloudData = await getCloudBin(binId);
            if (cloudData && Array.isArray(cloudData)) {
                // If cloud data is newer or has content, sync it down
                setOrders(cloudData);
                setCloudStatus('connected');
                setCloudBinId(binId);
            } else {
                setCloudStatus('error');
            }
        } else {
            // Create a fresh bin for this install
            const newBinId = await createCloudBin(existingOrders);
            if (newBinId) {
                localStorage.setItem('tini_cloud_bin_id', newBinId);
                setCloudBinId(newBinId);
                setCloudStatus('connected');
            } else {
                setCloudStatus('error');
            }
        }
    } catch (err) {
        console.error("Cloud connection failed", err);
        setCloudStatus('error');
    }
  }, []);

  useEffect(() => {
    const initialize = async () => {
        // Always load local data first for zero-latency start
        const savedOrders = localStorage.getItem('tini_orders');
        let localOrders: Order[] = [];
        if (savedOrders) {
            try { localOrders = JSON.parse(savedOrders); } catch(e) { console.error("Bad local storage JSON"); }
        }
        setOrders(localOrders);

        const savedPhone = localStorage.getItem('tini_customer_phone');
        if (savedPhone) setCustomerPhone(savedPhone);

        const savedRole = localStorage.getItem('tini_role');
        if (savedRole) {
            setRole(savedRole as Role);
            setActiveTab(savedRole === 'ADMIN' ? 'dashboard' : 'add');
        }

        // Try to connect to cloud in background
        connectToCloud(localOrders);

        // Hide splash screen after 2 seconds regardless of cloud status
        setTimeout(() => {
            setShowSplash(false);
            if (!savedRole) setShowWelcome(true);
        }, 2000);
    };

    initialize();
  }, [connectToCloud]);

  // --- Automatic Cloud Sync ---
  const syncToCloud = useCallback(async (data: Order[]) => {
    if (!cloudBinId) return;
