                <SidebarLink icon={ClipboardList} label="Daftar Order" active={activeTab === 'orders'} onClick={() => setActiveTab('orders')} />
                <SidebarLink icon={PlusCircle} label="Tambah Order" active={activeTab === 'add'} onClick={() => setActiveTab('add')} />
