    drawLine("TOTAL:", formatIDR(order.totalPrice));
    y += 10;
    doc.text("Terima kasih!", pageWidth / 2, y, { align: "center" });
    doc.save(`Nota_${order.notaNumber}.pdf`);
  };

  const handleConfirmAction = () => {
    if (!confirmData) return;
