        title={confirmData?.title || ''}
        message={confirmData?.msg || ''}
        confirmLabel={confirmData?.type === 'delete' ? "Hapus Sekarang" : "Ya, Lanjutkan"}
        isDanger={confirmData?.type === 'delete'}
