function StatCard({ label, value, icon: Icon, color }: any) {
  const colors: any = { blue: 'bg-blue-600', green: 'bg-green-600', orange: 'bg-orange-600', purple: 'bg-purple-600' };
  return (
    <Card className="hover:scale-[1.03] transition-all">
