                 `*TOTAL TAGIHAN: ${formatIDR(newOrder.totalPrice)}*\n\n` +
                 `Akses Tracking: ${window.location.origin}\n\n` +
                 `_Mohon segera diproses ya Bu Tini. Terima kasih!_`;

      // Step 4: Kirim ke WhatsApp (Eksplisit ke nomor Ibu Tini)
      setTimeout(() => {
        sendWhatsAppMessage("085695014434", msg);
        setActiveTab('orders');
      }, 150);

    } else {
      setToast({ message: "Gagal menyimpan ke server. Pesanan hanya tersimpan lokal.", type: 'danger' });
      // Tetap masukkan ke state lokal agar tidak hilang dari pandangan user saat offline
      setOrders(prev => [newOrder, ...prev]);
      throw new Error("DB_SAVE_FAILED");
    }

    setTimeout(() => setToast(null), 5000);
  };

  const updateOrderStatus = async (id: string, newStatus: OrderStatus) => {
    const order = orders.find(o => o.id === id);
    if (!order) return;

    const updatedOrder = { ...order, status: newStatus };
    setOrders(prev => prev.map(o => o.id === id ? updatedOrder : o));
    if (selectedOrder?.id === id) setSelectedOrder(updatedOrder);

    const success = await upsertOrderToSupabase(updatedOrder);
    if (success) {
        setToast({ message: `Status diperbarui: ${newStatus}`, type: 'success' });
    }
    setTimeout(() => setToast(null), 4000);
  };

  const handleDeleteOrder = async (id: string) => {
    const order = orders.find(o => o.id === id);
    if (!order) return;

    setOrders(prev => prev.filter(o => o.id !== id));

    const success = await deleteOrderFromSupabase(id);
    if (success) {
      setToast({ message: `Pesanan ${order.notaNumber} dihapus.`, type: 'danger' });
    }
    setTimeout(() => setToast(null), 5000);
  };

  const stats = useMemo(() => {
    const now = new Date();
    const todayStr = now.toDateString();

    // Omzet Hari Ini
    const incomeToday = orders
      .filter(o => new Date(o.createdAt).toDateString() === todayStr)
      .reduce((sum, o) => sum + o.totalPrice, 0);

    // Omzet Minggu Ini (7 hari terakhir)
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(now.getDate() - 7);
    const incomeWeekly = orders
      .filter(o => new Date(o.createdAt) >= sevenDaysAgo)
      .reduce((sum, o) => sum + o.totalPrice, 0);

    // Omzet Bulan Ini
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    const monthlyOrders = orders.filter(o => {
      const d = new Date(o.createdAt);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const incomeMonthly = monthlyOrders.reduce((acc, curr) => acc + curr.totalPrice, 0);

    const completed = monthlyOrders.filter(o => o.status === 'Selesai').length;
    const process = monthlyOrders.filter(o => o.status === 'Proses').length;

    // Data Grafik 7 Hari
    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - (6 - i));
      const dateStr = d.toLocaleDateString('id-ID', { weekday: 'short' });
      const dayTotal = orders
        .filter(o => new Date(o.createdAt).toDateString() === d.toDateString())
        .reduce((sum, o) => sum + o.totalPrice, 0);
      return { name: dateStr, revenue: dayTotal };
    });

    // Breakdown Layanan
    const serviceData = Object.keys(SERVICE_PRICES).map(s => {
      const count = orders.filter(o => o.serviceType === s).length;
      const total = orders.filter(o => o.serviceType === s).reduce((sum, o) => sum + o.totalPrice, 0);
      return { name: s, count, total };
    }).sort((a, b) => b.total - a.total);

    return { 
      incomeToday, 
      incomeWeekly, 
      incomeMonthly, 
      completed, 
      process, 
      chartData: last7Days,
      serviceData
    };
  }, [orders]);

  const filteredOrders = useMemo(() => {
    let result = orders;
    if (role === 'CUSTOMER' && customerPhone) result = result.filter(o => o.customerPhone === customerPhone);
    if (statusFilter !== 'Semua') result = result.filter(o => o.status === statusFilter);
    if (serviceFilter !== 'Semua') result = result.filter(o => o.serviceType === serviceFilter);
    if (startDate) {
      const start = new Date(startDate);
      start.setHours(0, 0, 0, 0);
      result = result.filter(o => new Date(o.createdAt) >= start);
