export const fetchOrdersFromSupabase = async (): Promise<Order[]> => {
  try {
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .order('createdAt', { ascending: false });

    if (error) throw error;
    return data || [];
  } catch (err) {
    console.error("Supabase fetch error:", err);
    return [];
  }
};

export const upsertOrderToSupabase = async (order: Order): Promise<boolean> => {
  try {
    // Pastikan tidak ada field 'undefined' yang dikirim ke database
    const cleanOrder = JSON.parse(JSON.stringify(order));

    const { error } = await supabase
      .from('orders')
      .upsert(cleanOrder);

    if (error) throw error;
    return true;
  } catch (err) {
    console.error("Supabase upsert error:", err);
    return false;
  }
};

export const deleteOrderFromSupabase = async (id: string): Promise<boolean> => {
  try {
    const { error } = await supabase
      .from('orders')
      .delete()
      .eq('id', id);

    if (error) throw error;
    return true;
  } catch (err) {
    console.error("Supabase delete error:", err);
    return false;
  }
};

