      setCustomerProfile({ name: newOrder.customerName, address: newOrder.customerAddress });

      if (orderSuccess) {
        setToast({ message: `Nota ${newOrder.notaNumber} BERHASIL DISIMPAN KE SERVER!`, type: 'success' });
