export const deleteOrderFromSupabase = async (id: string): Promise<boolean> => {
  try {
    const { error } = await supabase
      .from('orders')
      .delete()
      .eq('id', id);

    if (error) throw error;
    return true;
  } catch (err) {
    console.error("Supabase delete error:", err);
    return false;
  }
};

export const fetchCustomerFromSupabase = async (phone: string) => {
  try {
    const { data, error } = await supabase
      .from('customers')
      .select('*')
      .eq('phone', phone)
      .single();
    if (error && error.code !== 'PGRST116') throw error;
    return data;
  } catch (err) {
    console.warn("Supabase customer not found or error:", err);
    return null;
  }
};

export const upsertCustomerToSupabase = async (phone: string, name: string, address: string) => {
  try {
    const { error } = await supabase
      .from('customers')
      .upsert({ 
        phone, 
        name, 
        address, 
        lastSeen: new Date().toISOString() 
      });
    if (error) throw error;
    return true;
  } catch (err) {
    console.error("Supabase upsert customer error:", err);
    return false;
  }
};

