          <div className={`h-2 ${statusColors[order.status]}`}></div>
          <div className="px-6 py-5 flex justify-between items-center border-b bg-slate-50/50">
            <div className="flex items-center gap-3">
              <span className={`px-2.5 py-1 rounded-xl text-[10px] font-black text-white uppercase tracking-wider ${statusColors[order.status]}`}>{order.status}</span>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{order.notaNumber}</p>
              {!order.synced && <CloudUpload className="w-4 h-4 text-orange-400 animate-pulse" />}
            </div>
            <div className="flex items-center gap-2">
              {isAdmin && (
                <button 
                  onClick={() => setConfirmData({
                    type: 'delete',
                    title: 'Hapus Pesanan?',
                    msg: `Tindakan ini tidak dapat dibatalkan. Apakah Anda yakin ingin menghapus pesanan ${order.notaNumber}?`
                  })}
                  className="p-3 hover:bg-red-50 rounded-2xl transition-all text-slate-400 hover:text-red-500"
                  title="Hapus Order"
                >
                  <Trash2 className="w-5 h-5" />
                </button>
              )}
              <button onClick={onClose} className="p-3 hover:bg-slate-100 rounded-2xl transition-all text-slate-400">
                <X className="w-5 h-5" />
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-6 md:p-8 space-y-8">
            <section className="bg-blue-50/80 rounded-[2rem] p-6 border border-blue-100/50 relative overflow-hidden">
              <div className="absolute top-0 right-0 p-4 opacity-10"><UserCircle className="w-20 h-20" /></div>
              <div className="flex items-start gap-5 relative z-10">
                <div className="w-16 h-16 bg-white rounded-2xl shadow-sm flex items-center justify-center text-blue-600 shrink-0">
                  <UserCircle className="w-10 h-10" />
                </div>
                <div className="flex-1 min-w-0">
                  <h3 className="text-2xl font-black text-slate-900 truncate tracking-tight">{order.customerName}</h3>
                  <a href={`tel:${order.customerPhone}`} className="text-sm font-bold text-blue-600 flex items-center gap-2 mt-1 hover:underline">
                    <Phone className="w-4 h-4" /> {order.customerPhone}
                  </a>
                </div>
              </div>
              <div className="mt-6 flex items-start gap-3 text-sm text-slate-600 font-semibold leading-relaxed">
                <MapPin className="w-5 h-5 text-blue-400 shrink-0 mt-0.5" />
                <span>{order.customerAddress}</span>
              </div>
            </section>

            <div className="grid grid-cols-2 gap-4">
              <DetailBox icon={Shirt} label="Layanan" value={order.serviceType} />
              <DetailBox icon={Package} label="Berat/Qty" value={`${order.weight} ${order.serviceType.includes('Cuci') ? 'Kg' : 'Unit'}`} />
              <DetailBox icon={CalendarDays} label="Tanggal" value={new Date(order.createdAt).toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })} />
              <DetailBox icon={Truck} label="Pengiriman" value={order.deliveryMethod} />
            </div>

            {order.specialRequest && (
              <div className="bg-orange-50/50 rounded-[1.5rem] p-5 border border-orange-100">
                <div className="flex items-center gap-2 mb-2">
                  <Info className="w-4 h-4 text-orange-500" />
                  <p className="text-[10px] font-black text-orange-600 uppercase tracking-widest">Catatan Khusus</p>
                </div>
                <p className="font-bold text-orange-900 text-sm italic leading-relaxed">"{order.specialRequest}"</p>
              </div>
            )}

            <div className="bg-slate-900 text-white rounded-[2rem] p-7 shadow-xl flex items-center justify-between group overflow-hidden relative">
              <div className="absolute -right-4 -top-4 opacity-10 group-hover:scale-110 transition-transform duration-700">
                 <Coins className="w-32 h-32" />
              </div>
              <div className="relative z-10">
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2">Total Bayar</p>
                <p className="text-4xl font-black tracking-tighter">{formatIDR(order.totalPrice)}</p>
              </div>
            </div>
          </div>

          <div className="p-6 md:p-8 bg-slate-50 border-t flex flex-col gap-4">
            <div className="grid grid-cols-3 gap-3">
              <button onClick={generatePDF} className="flex items-center justify-center gap-2 bg-white border border-slate-200 text-slate-700 py-4 rounded-2xl font-black text-[9px] uppercase tracking-widest transition-all hover:bg-slate-50 active:scale-95 shadow-sm">
                <Printer className="w-4 h-4" /> NOTA
              </button>
              <button onClick={handleContact} className="flex items-center justify-center gap-2 bg-green-50 text-green-700 py-4 rounded-2xl font-black text-[9px] uppercase tracking-widest transition-all hover:bg-green-100 active:scale-95 shadow-sm border border-green-100">
                <MessageCircle className="w-4 h-4" /> CUSTOMER
              </button>
              <button onClick={handleContactOwner} className="flex items-center justify-center gap-2 bg-blue-50 text-blue-700 py-4 rounded-2xl font-black text-[9px] uppercase tracking-widest transition-all hover:bg-blue-100 active:scale-95 shadow-sm border border-blue-100">
                <Headphones className="w-4 h-4" /> OWNER
              </button>
            </div>

            {isAdmin && (
              <div className="mt-1">
                {order.status === 'Baru' && (
                  <Button onClick={() => setConfirmData({ 
                      type: 'status',
                      status: 'Proses', 
                      title: 'Mulai Pengerjaan?', 
                      msg: `Ubah status ${order.customerName} menjadi 'Proses'?` 
                  })} className="w-full py-5 text-sm font-black tracking-widest uppercase bg-orange-500 hover:bg-orange-600">
                    MULAI PROSES PENGERJAAN
                  </Button>
                )}
                {order.status === 'Proses' && (
                  <Button onClick={() => setConfirmData({ 
                      type: 'status',
                      status: 'Selesai', 
                      title: 'Selesaikan Order?', 
                      msg: `Kirim notifikasi ke ${order.customerName} bahwa pesanan sudah selesai?` 
                  })} variant="success" className="w-full py-5 text-sm font-black tracking-widest uppercase">
                    SELESAIKAN & KIRIM NOTIFIKASI
                  </Button>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </>
  );
};

function DetailBox({ icon: Icon, label, value }: any) {
  return (
    <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 transition-all hover:bg-white hover:shadow-sm">
      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2 flex items-center gap-2">
         <Icon className="w-3.5 h-3.5" /> {label}
      </p>
      <p className="font-bold text-slate-800 text-sm truncate">{value}</p>
    </div>
  );
}

// --- Main App Component ---

export default function App() {
  const [role, setRole] = useState<Role | null>(null);
  const [customerPhone, setCustomerPhone] = useState<string>('');
  const [customerProfile, setCustomerProfile] = useState<{name: string, address: string} | null>(null);
  const [orders, setOrders] = useState<AppOrder[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [showSplash, setShowSplash] = useState(true);
  const [showWelcome, setShowWelcome] = useState(false);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'orders' | 'add' | 'reports' | 'settings'>('dashboard');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<'Semua' | OrderStatus>('Semua');
  const [serviceFilter, setServiceFilter] = useState<ServiceType | 'Semua'>('Semua');
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'info' | 'danger' } | null>(null);
  const [selectedOrder, setSelectedOrder] = useState<AppOrder | null>(null);
  const [dbStatus, setDbStatus] = useState<'offline' | 'syncing' | 'live'>('offline');
  const [appSettings, setAppSettings] = useState<AppSettings>({
    soundEnabled: true,
    pushEnabled: true
  });

  const syncLock = useRef(false);

  // Auth state for Admin
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminUsernameInput, setAdminUsernameInput] = useState('');
  const [adminPinInput, setAdminPinInput] = useState('');
  const [adminAuthError, setAdminAuthError] = useState(false);

  // Persist settings
  useEffect(() => {
    const savedSettings = localStorage.getItem('tini_settings');
    if (savedSettings) {
      setAppSettings(JSON.parse(savedSettings));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('tini_settings', JSON.stringify(appSettings));
  }, [appSettings]);

  const syncCustomerProfile = useCallback(async (phone: string) => {
    if (!isSupabaseConfigured()) return;
    try {
        const profile = await fetchCustomerFromSupabase(phone);
        if (profile) {
            setCustomerProfile({ name: profile.name, address: profile.address });
        }
    } catch (e) {
        console.warn("Profile sync error", e);
    }
  }, []);

  const initializeSupabase = useCallback(async () => {
    setDbStatus('syncing');

    // Always start with local storage to avoid empty screens
    const saved = localStorage.getItem('tini_orders');
    let currentOrders: AppOrder[] = saved ? JSON.parse(saved) : [];
    setOrders(currentOrders);

    if (!isSupabaseConfigured()) {
      setDbStatus('offline');
      return;
    }

    try {
      const remoteOrders = await fetchOrdersFromSupabase();

      // Merge logic: Remote is source of truth, but keep local "synced: false" flags for pending items
      const mergedOrdersMap = new Map<string, AppOrder>();

      // Load local ones first
      currentOrders.forEach(o => mergedOrdersMap.set(o.id, { ...o, synced: o.synced ?? false }));

      // Remote ones overwrite local ones and are definitely synced
      remoteOrders.forEach(ro => mergedOrdersMap.set(ro.id, { ...ro, synced: true }));

      const finalOrders = Array.from(mergedOrdersMap.values())
        .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

      setOrders(finalOrders);
      localStorage.setItem('tini_orders', JSON.stringify(finalOrders));
      setDbStatus('live');

      if (customerPhone) {
        syncCustomerProfile(customerPhone);
      }

      // Realtime subscription
      const channel = supabase
        .channel('public:orders')
        .on(
          'postgres_changes',
          { event: '*', schema: 'public', table: 'orders' },
          (payload) => {
            if (payload.eventType === 'INSERT') {
              const newOrder = payload.new as AppOrder;
              setOrders(prev => {
                if (prev.some(o => o.id === newOrder.id)) return prev;
                return [{ ...newOrder, synced: true }, ...prev];
              });

              if (role === 'ADMIN') {
                if (appSettings.soundEnabled) playNotificationSound();
                if (appSettings.pushEnabled) showPushNotification("Pesanan Baru!", `Pesanan dari ${newOrder.customerName} telah diterima.`);

                setToast({ message: "Pesanan Baru Masuk Cloud! 🧺", type: 'success' });
                setTimeout(() => setToast(null), 5000);
              }
            } else if (payload.eventType === 'UPDATE') {
              const updatedOrder = payload.new as AppOrder;
              setOrders(prev => prev.map(o => o.id === updatedOrder.id ? { ...updatedOrder, synced: true } : o));
            } else if (payload.eventType === 'DELETE') {
              setOrders(prev => prev.filter(o => o.id !== payload.old.id));
            }
          }
        )
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
      };
    } catch (err) {
      console.error("Supabase connection error:", err);
      setDbStatus('offline');
    }
  }, [role, customerPhone, syncCustomerProfile, appSettings.soundEnabled, appSettings.pushEnabled]);

  // Effect to handle initialization and real-time cleanup correctly
  useEffect(() => {
    let cleanup: (() => void) | undefined;
    const run = async () => {
      const res = await initializeSupabase();
      if (typeof res === 'function') cleanup = res;
    };
    run();
    return () => { if (cleanup) cleanup(); };
  }, [initializeSupabase]);

  useEffect(() => {
    const savedPhone = localStorage.getItem('tini_customer_phone');
    if (savedPhone) setCustomerPhone(savedPhone);

    const savedRole = localStorage.getItem('tini_role');
    if (savedRole) {
      setRole(savedRole as Role);
      setActiveTab(savedRole === 'ADMIN' ? 'dashboard' : 'orders');
    }

    setTimeout(() => {
      setShowSplash(false);
      if (!savedRole) setShowWelcome(true);
    }, 2000);
  }, []);

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (adminPinInput === ADMIN_PIN && adminUsernameInput === ADMIN_USERNAME) {
      setRole('ADMIN');
      localStorage.setItem('tini_role', 'ADMIN');
      setActiveTab('dashboard');
      setShowAdminLogin(false);
      setAdminUsernameInput('');
      setAdminPinInput('');
      setAdminAuthError(false);
    } else {
      setAdminAuthError(true);
      setAdminPinInput('');
    }
  };

  const handleRoleSelect = (selectedRole: Role) => {
    if (selectedRole === 'ADMIN') {
      setShowAdminLogin(true);
    } else {
      setRole(selectedRole);
      localStorage.setItem('tini_role', selectedRole);
      setActiveTab('orders');
    }
  };

  const handleLogout = () => {
    setRole(null);
    setCustomerPhone('');
    setCustomerProfile(null);
    localStorage.removeItem('tini_role');
    localStorage.removeItem('tini_customer_phone');
    setShowAdminLogin(false);
    setShowWelcome(true);
  };

  const addOrder = async (newOrder: AppOrder) => {
    // Optimistic UI update
    const optimisticOrder = { ...newOrder, synced: false };
    const updatedOrders = [optimisticOrder, ...orders];
    setOrders(updatedOrders);
    localStorage.setItem('tini_orders', JSON.stringify(updatedOrders));

    if (appSettings.soundEnabled) playNotificationSound();
    setToast({ message: "Menyimpan pesanan...", type: 'info' });

    if (!isSupabaseConfigured()) {
      setToast({ message: "Offline: Tersimpan di perangkat (Database belum dikonfigurasi).", type: 'info' });
      setTimeout(() => setToast(null), 5000);
      setActiveTab('orders');
      return;
    }

    try {
      // 1. Customer Sync
      upsertCustomerToSupabase(newOrder.customerPhone, newOrder.customerName, newOrder.customerAddress)
        .then(() => setCustomerProfile({ name: newOrder.customerName, address: newOrder.customerAddress }))
        .catch(e => console.warn("Customer auto-sync failed", e));

      // 2. Order Sync
      const success = await upsertOrderToSupabase(newOrder);
      if (success) {
        setOrders(prev => prev.map(o => o.id === newOrder.id ? { ...o, synced: true } : o));
        setToast({ message: `Nota ${newOrder.notaNumber} BERHASIL DISIMPAN KE CLOUD!`, type: 'success' });
      } else {
        setToast({ message: "Gagal sinkron server, data tetap aman di perangkat.", type: 'danger' });
      }

      // 3. WhatsApp Integration
      const msg = `*PESANAN BARU - LAUNDRY IBU TINI*\n` +
                 `------------------------------------\n` +
                 `Nota: *${newOrder.notaNumber}*\n` +
                 `Tanggal: ${new Date(newOrder.createdAt).toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long' })}\n\n` +
                 `*PELANGGAN*\n` +
                 `Nama: *${newOrder.customerName}*\n` +
                 `Alamat: ${newOrder.customerAddress}\n\n` +
                 `*LAYANAN*\n` +
                 `Layanan: *${newOrder.serviceType}*\n` +
                 `Berat/Qty: ${newOrder.weight} Unit/Kg\n` +
                 `------------------------------------\n` +
                 `*TOTAL: ${formatIDR(newOrder.totalPrice)}*\n\n` +
                 `Lacak: ${window.location.origin}`;

      setTimeout(() => {
        sendWhatsAppMessage(OWNER_PHONE, msg);
        setActiveTab('orders');
      }, 500);

    } catch (err) {
      console.error("Critical Sync Error:", err);
    }

    setTimeout(() => setToast(null), 5000);
  };

  const updateOrderStatus = async (id: string, newStatus: OrderStatus) => {
    const order = orders.find(o => o.id === id);
    if (!order) return;

    const updatedOrder = { ...order, status: newStatus, synced: false };
    const updatedOrders = orders.map(o => o.id === id ? updatedOrder : o);
    setOrders(updatedOrders);
    localStorage.setItem('tini_orders', JSON.stringify(updatedOrders));

    if (selectedOrder?.id === id) setSelectedOrder(updatedOrder);

    if (!isSupabaseConfigured()) return;

    const success = await upsertOrderToSupabase(updatedOrder);
    if (success) {
        setOrders(prev => prev.map(o => o.id === id ? { ...o, synced: true } : o));
        setToast({ message: `Status diperbarui: ${newStatus}`, type: 'success' });
    } else {
        setToast({ message: "Status diperbarui lokal (Menunggu Online)", type: 'info' });
    }
    setTimeout(() => setToast(null), 4000);
  };

  const handleDeleteOrder = async (id: string) => {
    const updatedOrders = orders.filter(o => o.id !== id);
    setOrders(updatedOrders);
    localStorage.setItem('tini_orders', JSON.stringify(updatedOrders));

    if (!isSupabaseConfigured()) return;

    const success = await deleteOrderFromSupabase(id);
    if (success) {
      setToast({ message: `Pesanan dihapus selamanya.`, type: 'danger' });
    }
    setTimeout(() => setToast(null), 5000);
  };

  const retrySyncAll = async () => {
    if (syncLock.current) return;
    const unsynced = orders.filter(o => !o.synced);
    if (unsynced.length === 0) {
      setToast({ message: "Semua data sudah sinkron!", type: 'success' });
      return;
    }

    if (!isSupabaseConfigured()) {
        setToast({ message: "Gagal: Database belum dikonfigurasi.", type: 'danger' });
        return;
    }

    syncLock.current = true;
    setDbStatus('syncing');
    let count = 0;

    try {
        for (const o of unsynced) {
          const success = await upsertOrderToSupabase(o);
          if (success) {
            setOrders(prev => prev.map(item => item.id === o.id ? { ...item, synced: true } : item));
            count++;
          }
        }
        setToast({ message: `${count} data berhasil diunggah ke cloud.`, type: 'success' });
    } finally {
        setDbStatus('live');
        syncLock.current = false;
        setTimeout(() => setToast(null), 4000);
    }
  };

  const stats = useMemo(() => {
    const now = new Date();
    const todayStr = now.toDateString();

    const incomeToday = orders
      .filter(o => new Date(o.createdAt).toDateString() === todayStr)
      .reduce((sum, o) => sum + o.totalPrice, 0);

    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(now.getDate() - 7);
    const incomeWeekly = orders
      .filter(o => new Date(o.createdAt) >= sevenDaysAgo)
      .reduce((sum, o) => sum + o.totalPrice, 0);

    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();
    const monthlyOrders = orders.filter(o => {
      const d = new Date(o.createdAt);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });
    const incomeMonthly = monthlyOrders.reduce((acc, curr) => acc + curr.totalPrice, 0);

    const completed = monthlyOrders.filter(o => o.status === 'Selesai').length;
    const process = monthlyOrders.filter(o => o.status === 'Proses').length;

    const last7Days = [...Array(7)].map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - (6 - i));
      const dateStr = d.toLocaleDateString('id-ID', { weekday: 'short' });
      const dayTotal = orders
        .filter(o => new Date(o.createdAt).toDateString() === d.toDateString())
        .reduce((sum, o) => sum + o.totalPrice, 0);
      return { name: dateStr, revenue: dayTotal };
    });

    const serviceData = Object.keys(SERVICE_PRICES).map(s => {
      const count = orders.filter(o => o.serviceType === s).length;
      const total = orders.filter(o => o.serviceType === s).reduce((sum, o) => sum + o.totalPrice, 0);
      return { name: s, count, total };
    }).sort((a, b) => b.total - a.total);

    return { 
      incomeToday, 
      incomeWeekly, 
      incomeMonthly, 
      completed, 
      process, 
      chartData: last7Days,
      serviceData
    };
  }, [orders]);

  const filteredOrders = useMemo(() => {
    let result = orders;
    if (role === 'CUSTOMER' && customerPhone) result = result.filter(o => o.customerPhone === customerPhone);
    if (statusFilter !== 'Semua') result = result.filter(o => o.status === statusFilter);
    if (serviceFilter !== 'Semua') result = result.filter(o => o.serviceType === serviceFilter);
    if (startDate) {
      const start = new Date(startDate);
      start.setHours(0, 0, 0, 0);
      result = result.filter(o => new Date(o.createdAt) >= start);
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      result = result.filter(o => new Date(o.createdAt) <= end);
    }
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter(o => o.customerName.toLowerCase().includes(q) || o.notaNumber.toLowerCase().includes(q));
    }
    return result;
  }, [orders, role, customerPhone, searchQuery, statusFilter, serviceFilter, startDate, endDate]);

  const customerStats = useMemo(() => {
    if (role !== 'CUSTOMER') return null;
    const myOrders = orders.filter(o => o.customerPhone === customerPhone);
    return {
      total: myOrders.length,
      active: myOrders.filter(o => o.status !== 'Selesai').length,
      done: myOrders.filter(o => o.status === 'Selesai').length,
    };
  }, [orders, role, customerPhone]);

  const dbConfigured = isSupabaseConfigured();

  if (showSplash) {
    return (
      <div className="fixed inset-0 bg-blue-600 flex items-center justify-center flex-col text-white z-[1000] p-6 text-center">
        <WashingMachine className="w-20 h-20 animate-bounce mb-6" />
        <h1 className="text-4xl font-black tracking-tighter uppercase mb-2">LAUNDRY IBU TINI</h1>
        <p className="text-blue-100 font-bold opacity-80 uppercase tracking-widest text-[10px]">Professional Management System</p>
      </div>
    );
  }

  if (showWelcome) {
    return (
      <div className="min-h-screen relative overflow-hidden flex flex-col">
        <div className="relative z-10 max-w-7xl mx-auto px-6 pt-12 pb-24 min-h-screen flex flex-col w-full">
          <div className="flex items-center gap-2 mb-12 md:mb-24 animate-fade-in">
             <div className="w-10 h-10 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-100">
                <WashingMachine className="w-6 h-6" />
             </div>
             <span className="text-xl font-black tracking-tighter text-slate-900">LAUNDRY IBU TINI</span>
          </div>

